/* Size charts by collection and category (round 13, run after part 283): a size chart can also be given to every product in some of the store's collections (size_charts.collection_ids, a list of collection ids, at most 50) or with some categories (size_charts.categories, a list of category names as the product editor files them, like T-Shirts, at most 50). A product page shows the chart chosen on the product first, then a chart set for one of its collections, then one set for its category, then the size guide block's own table. Two new columns with an empty list as their default, so every chart saved before keeps showing only on the products it was given. Read by the product page on Storelib themes, imported themes and the OnePage, written by Products > Size charts through /api/size-charts. Row level security and grants are as part 283 left them. Until it runs a chart shows only on the products it was given, and the chart editor says this part is needed for collections and categories. No rows change. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.size_charts') IS NULL THEN RAISE NOTICE 'part 309: size_charts is not here yet; run part 283 first, then this again.'; RETURN; END IF; ALTER TABLE public.size_charts ADD COLUMN IF NOT EXISTS collection_ids uuid[] NOT NULL DEFAULT '{}'::uuid[]; ALTER TABLE public.size_charts ADD COLUMN IF NOT EXISTS categories text[] NOT NULL DEFAULT '{}'::text[]; ALTER TABLE public.size_charts DROP CONSTRAINT IF EXISTS size_charts_rules_len; ALTER TABLE public.size_charts ADD CONSTRAINT size_charts_rules_len CHECK (coalesce(array_length(collection_ids, 1), 0) <= 50 AND coalesce(array_length(categories, 1), 0) <= 50); END $do$;
DO $do$ BEGIN IF to_regclass('public.size_charts') IS NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS size_charts_collection_ids_idx ON public.size_charts USING gin (collection_ids); END $do$;
notify pgrst, 'reload schema';
